import gzip,csv,glob,re,collections
for f in sorted(glob.glob('studies/data/raw/*matrix*')):
 rows=[r for r in csv.reader(gzip.open(f,'rt'),delimiter='\t') if r and r[0].startswith('!Sample_')]
 ids=next(r[1:] for r in rows if r[0]=='!Sample_geo_accession')
 print('\n',f)
 for r in rows:
  if any(re.search(r'\brep(?:licate)?\s*\d',v,re.I) for v in r[1:]) and r[0]!='!Sample_title':
   for g,v in zip(ids,r[1:]):print(g,r[0],v)
 titles=next(r[1:] for r in rows if r[0]=='!Sample_title')
 norm=[re.sub(r'\s*\(MD\d+\)','',v) for v in titles]
 counts=collections.Counter(norm)
 for g,v in zip(ids,norm):
  if counts[v]>1: print('DUP',g,v)
